package com.consense.service.drafting;

import com.consense.common.JsonUtils;
import com.consense.document.DocxTemplateEditor.*;
import java.nio.file.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.w3c.dom.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.junit.jupiter.api.Assumptions.assumeTrue;
import static com.consense.service.drafting.DraftNativeStoryEditorCandidateTest.*;

/** Existing native row/hint/gap actions share one prepared source; final renderer quality is separate. */
class DraftSctRowLatinFamilyCandidateTest {
    private static final String ROW="keep_verified_row_together",HINT="normalize_verified_latin_font_hint",GAP="compact_verified_row_gaps";
    private static final String PPR="<w:pPr><w:spacing w:before=\"120\" w:after=\"60\" w:beforeLines=\"50\" w:afterLines=\"25\"/><w:jc w:val=\"both\"/></w:pPr>";
    private static byte[] source()throws Exception{
        return new Fixture(p("Before")+"<w:tbl><w:tblPr/><w:tblGrid><w:gridCol w:w=\"5000\"/><w:gridCol w:w=\"2000\"/></w:tblGrid><w:tr><w:trPr><w:trHeight w:val=\"853\"/></w:trPr><w:tc><w:p>"+PPR+"<w:r><w:rPr><w:rFonts w:ascii=\"Times New Roman\" w:eastAsia=\"Adobe Heiti Std R\" w:hint=\"eastAsia\"/><w:sz w:val=\"24\"/></w:rPr><w:t>Latin “quoted” text</w:t></w:r></w:p></w:tc><w:tc><w:p>"+PPR+"<w:r><w:t>Reference</w:t></w:r></w:p></w:tc></w:tr></w:tbl>"+p("After")+"<w:sectPr/>","",Collections.emptyMap(),"").bytes;
    }
    private static NativeLayoutPlan shared(TemplateIndex index){
        Paragraph p=index.mainParagraph(2);NodeAnchor row=index.anchor(p.getRowId());
        return new NativeLayoutPlan(index.getSourceSha256(),"synthetic-shared-source-row-hint-gap",List.of(),List.of(),List.of(),List.of(row),List.of(row)).withLatinFontHintParagraphs(List.of(index.anchor(p.getId())));
    }
    private static DocxEditResult apply(byte[] source,NativeLayoutPlan plan,List<Edit> edits){return EDITOR.applyWithParagraphBookmarks(source,new SourceEditBatch(EDITOR.inspect(source).getSourceSha256(),edits),Collections.emptyMap(),false,plan);}
    private static List<Element> children(Element p,String name){List<Element> result=new ArrayList<>();for(Node n=p.getFirstChild();n!=null;n=n.getNextSibling())if(n instanceof Element&&W.equals(n.getNamespaceURI())&&name.equals(n.getLocalName()))result.add((Element)n);return result;}
    private static Element at(Document d,String id){Element node=d.getDocumentElement();String[] parts=id.split("#",2)[1].split("/");for(int i=2;i<parts.length;i++){String part=parts[i];int left=part.indexOf('['),right=part.indexOf(']');String name=part.substring(2,left);node=children(node,name).get(Integer.parseInt(part.substring(left+1,right))-1);}return node;}
    private static void undoMarkers(Document after,List<NativeLayoutChange> changes){
        Set<String> names=new HashSet<>(),ids=new HashSet<>();for(NativeLayoutChange change:changes)if(change.getLayoutId()!=null)names.add(change.getLayoutId());
        List<Element> remove=new ArrayList<>();for(Element node:elements(after,W,"bookmarkStart"))if(names.contains(node.getAttributeNS(W,"name"))){ids.add(node.getAttributeNS(W,"id"));remove.add(node);}assertEquals(names.size(),remove.size());
        for(Element node:elements(after,W,"bookmarkEnd"))if(ids.contains(node.getAttributeNS(W,"id")))remove.add(node);assertEquals(2*names.size(),remove.size());for(Element node:remove)node.getParentNode().removeChild(node);
    }
    private static String shape(Node node){StringBuilder out=new StringBuilder();shape(node,out);return out.toString();}
    private static void shape(Node node,StringBuilder out){if(node instanceof Element){out.append('<').append(node.getNamespaceURI()).append('|').append(node.getLocalName());Map<String,String> attributes=new TreeMap<>();NamedNodeMap raw=node.getAttributes();for(int i=0;i<raw.getLength();i++){Node a=raw.item(i);if(!"http://www.w3.org/2000/xmlns/".equals(a.getNamespaceURI()))attributes.put("{"+a.getNamespaceURI()+"}"+a.getLocalName(),a.getNodeValue());}out.append(attributes).append('>');for(Node child=node.getFirstChild();child!=null;child=child.getNextSibling())shape(child,out);out.append("</>");}else if(node.getNodeType()==Node.TEXT_NODE||node.getNodeType()==Node.CDATA_SECTION_NODE)out.append(node.getNodeValue());}
    private static List<Object> rows(Map<String,Object> source,String key){return DraftBusinessRules.list(source.get(key));}
    private Map<String,Object> expected()throws Exception{return JsonUtils.mapper().readValue(getClass().getResourceAsStream("/drafting/sct-row-latin-source-family.json"),Map.class);}

    @Test void actualComplete143RowRegistryUsesTrueJavaSourceAnchorsAndChangesOnlyCohesionAndMarkers()throws Exception{
        String dir=System.getProperty("consense.acceptance.sourceDir");assumeTrue(dir!=null,"Explicit original2a source required");byte[] bytes=Files.readAllBytes(Paths.get(dir,"02_Special Conditions of Tender (SCT).docx"));TemplateIndex index=EDITOR.inspect(bytes);Map<String,Object> fixture=expected();assertEquals(fixture.get("sourceSha256"),index.getSourceSha256());
        Map<String,Object> registry=JsonUtils.mapper().readValue(getClass().getResourceAsStream("/drafting/libreoffice-native-layout.json"),Map.class);Map<String,Object> registered=rows(registry,"sources").stream().map(DraftBusinessRules::asMap).filter(r->index.getSourceSha256().equals(r.get("sourceSha256"))).findFirst().orElseThrow(AssertionError::new);assertEquals(rows(fixture,"cohesiveRows"),rows(registered,"cohesiveRows").subList(0,143));assertEquals(rows(fixture,"latinFontHintParagraphs"),registered.get("latinFontHintParagraphs"));assertNotNull(DraftNativeLayout.plan(index,"SCT","libreoffice"));
        List<NodeAnchor> anchors=new ArrayList<>();for(Object raw:rows(fixture,"cohesiveRows")){Map<String,Object> target=DraftBusinessRules.asMap(raw);NodeAnchor anchor=index.anchor(String.valueOf(target.get("rowId")));assertEquals("tr",anchor.getKind());assertEquals(target.get("rowSha256"),anchor.getSha256());anchors.add(anchor);}assertEquals(143,anchors.size());
        NativeLayoutPlan plan=new NativeLayoutPlan(index.getSourceSha256(),"actual-complete-source-row-class",List.of(),List.of(),List.of(),anchors);DocxEditResult result=apply(bytes,plan,List.of());assertEquals(143,result.getNativeLayoutLedger().size());
        Document before=parse(unzip(bytes).get(MAIN)),after=parse(unzip(result.getDocxBytes()).get(MAIN));
        for(NativeLayoutChange change:result.getNativeLayoutLedger()){assertEquals(ROW,change.getAction());assertEquals("APPLIED",change.getStatus());assertTrue(result.getIndex().paragraph(change.getGeneratedId()).hasNativeRowCohesion());Element original=at(before,change.getSource().getId()),current=at(after,change.getSource().getId());List<Element> props=children(current,"trPr");assertEquals(1,props.size());List<Element> switches=children(props.get(0),"cantSplit");assertEquals(1,switches.size());assertEquals("1",switches.get(0).getAttributeNS(W,"val"));assertTrue(children(original,"trPr").isEmpty()||children(children(original,"trPr").get(0),"cantSplit").isEmpty());props.get(0).removeChild(switches.get(0));if(children(original,"trPr").isEmpty()){assertFalse(props.get(0).hasChildNodes());current.removeChild(props.get(0));}}
        undoMarkers(after,result.getNativeLayoutLedger());String beforeShape=shape(before.getDocumentElement()),afterShape=shape(after.getDocumentElement());assertFalse(beforeShape.isEmpty(),"Whole main XML observation must be nonempty");assertEquals(beforeShape,afterShape,"All source text, fonts, sizes, fields, page controls, grid and heights survive exact inverse");unchanged(unzip(bytes),unzip(result.getDocxBytes()),Set.of(MAIN));assertEquals(index.getSourceSha256(),EDITOR.inspect(bytes).getSourceSha256());
    }
    @Test void samePreparedRowAppliesLatinHintCohesionAndCompactionAndKeepsSourceInverse()throws Exception{
        byte[] bytes=source();TemplateIndex index=EDITOR.inspect(bytes);DocxEditResult result=apply(bytes,shared(index),List.of());assertEquals(3,result.getNativeLayoutLedger().size());Set<String> actions=new HashSet<>();for(NativeLayoutChange c:result.getNativeLayoutLedger()){assertEquals("APPLIED",c.getStatus());actions.add(c.getAction());}assertEquals(Set.of(ROW,HINT,GAP),actions);Paragraph saved=result.getIndex().mainParagraph(2);assertTrue(saved.hasNativeRowCohesion());assertTrue(saved.hasCompactNativeRowGaps());assertTrue(saved.hasNormalizedNativeLatinFontHints());assertEquals(index.mainParagraph(2).getText(),saved.getText());
        Document before=parse(unzip(bytes).get(MAIN)),after=parse(unzip(result.getDocxBytes()).get(MAIN));undoMarkers(after,result.getNativeLayoutLedger());Element original=at(before,index.mainParagraph(2).getRowId()),current=at(after,index.mainParagraph(2).getRowId());Element trPr=children(current,"trPr").get(0);assertTrue(children(trPr,"trHeight").isEmpty());trPr.removeChild(children(trPr,"cantSplit").get(0));trPr.appendChild(after.importNode(children(children(original,"trPr").get(0),"trHeight").get(0),true));
        NodeList beforeP=original.getElementsByTagNameNS(W,"p"),afterP=current.getElementsByTagNameNS(W,"p");assertEquals(beforeP.getLength(),afterP.getLength());for(int i=0;i<beforeP.getLength();i++){Element oldSpacing=children(children((Element)beforeP.item(i),"pPr").get(0),"spacing").get(0),newSpacing=children(children((Element)afterP.item(i),"pPr").get(0),"spacing").get(0);for(String attribute:List.of("before","after","beforeLines","afterLines"))assertEquals("0",newSpacing.getAttributeNS(W,attribute));newSpacing.getParentNode().replaceChild(after.importNode(oldSpacing,true),newSpacing);}
        NodeList fonts=current.getElementsByTagNameNS(W,"rFonts");assertEquals(1,fonts.getLength());assertFalse(((Element)fonts.item(0)).hasAttributeNS(W,"hint"));((Element)fonts.item(0)).setAttributeNS(W,"w:hint","eastAsia");String beforeShape=shape(before.getDocumentElement()),afterShape=shape(after.getDocumentElement());assertFalse(beforeShape.isEmpty(),"Whole main XML observation must be nonempty");assertEquals(beforeShape,afterShape,"Only the three authorized formatting operations and their persistent markers changed");unchanged(unzip(bytes),unzip(result.getDocxBytes()),Set.of(MAIN));
    }
    @Test void realBusinessEditOrClearKeepsOriginalLatinHashGateAndDuplicateRowsStayRejected()throws Exception{
        byte[] bytes=source();TemplateIndex index=EDITOR.inspect(bytes);Paragraph p=index.mainParagraph(2);
        for(Edit edit:List.of(Edit.replaceSpan("manual-edit",p,0,p.getText().length(),p.getText(),"Manual exact value"),Edit.clearParagraph("manual-clear",p))){DocxEditResult result=apply(bytes,shared(index),List.of(edit));Map<String,String> statuses=new HashMap<>();for(NativeLayoutChange c:result.getNativeLayoutLedger())statuses.put(c.getAction(),c.getStatus());assertEquals("SKIPPED_CHANGED",statuses.get(HINT));assertEquals("APPLIED",statuses.get(ROW));assertEquals("APPLIED",statuses.get(GAP));assertEquals(edit.getType()==EditType.CLEAR_PARAGRAPH?"":"Manual exact value",result.getIndex().mainParagraph(2).getText());assertTrue(elements(parse(unzip(result.getDocxBytes()).get(MAIN)),W,"rFonts").stream().allMatch(f->"eastAsia".equals(f.getAttributeNS(W,"hint"))));}
        NodeAnchor row=index.anchor(p.getRowId());for(NativeLayoutPlan invalid:List.of(new NativeLayoutPlan(index.getSourceSha256(),"duplicate-row",List.of(),List.of(),List.of(),List.of(row,row)),new NativeLayoutPlan(index.getSourceSha256(),"duplicate-gap",List.of(),List.of(),List.of(),List.of(row),List.of(row,row))))assertEquals("LAYOUT_ROW_SCOPE_CHANGED",assertThrows(EditException.class,()->apply(bytes,invalid,List.of())).getCode());assertEquals(index.getSourceSha256(),EDITOR.inspect(bytes).getSourceSha256());
    }
    @Test void actualComplete36HeadingAnd14BridgeRowsKeepNativeMergesAndAllOtherSourceXml()throws Exception{
        String dir=System.getProperty("consense.acceptance.sourceDir");assumeTrue(dir!=null,"Explicit original2a source required");byte[] bytes=Files.readAllBytes(Paths.get(dir,"02_Special Conditions of Tender (SCT).docx"));TemplateIndex index=EDITOR.inspect(bytes);
        Map<String,Object> family=JsonUtils.mapper().readValue(getClass().getResourceAsStream("/drafting/sct-heading-row-source-family.json"),Map.class);assertEquals(family.get("sourceSha256"),index.getSourceSha256());assertEquals(36,rows(family,"headingRowIds").size());assertEquals(50,rows(family,"cohesiveRows").size());assertEquals(2,rows(family,"mergedHeadingRowIds").size());
        Map<String,Object> registry=JsonUtils.mapper().readValue(getClass().getResourceAsStream("/drafting/libreoffice-native-layout.json"),Map.class);Map<String,Object> registered=rows(registry,"sources").stream().map(DraftBusinessRules::asMap).filter(r->index.getSourceSha256().equals(r.get("sourceSha256"))).findFirst().orElseThrow(AssertionError::new);List<Object> complete=new ArrayList<>(rows(expected(),"cohesiveRows"));complete.addAll(rows(family,"cohesiveRows"));assertEquals(193,complete.size());assertEquals(complete,rows(registered,"cohesiveRows"));assertEquals(218,rows(registered,"cellKeepNextParagraphs").size());assertEquals(231,rows(registered,"cellWidowParagraphs").size());assertNotNull(DraftNativeLayout.plan(index,"SCT","libreoffice"));
        List<NodeAnchor> anchors=new ArrayList<>();for(Object raw:rows(family,"cohesiveRows")){Map<String,Object> target=DraftBusinessRules.asMap(raw);NodeAnchor anchor=index.anchor(String.valueOf(target.get("rowId")));assertEquals("tr",anchor.getKind());assertEquals(target.get("rowSha256"),anchor.getSha256());anchors.add(anchor);}NativeLayoutPlan plan=new NativeLayoutPlan(index.getSourceSha256(),"complete-source-heading-row-and-empty-bridge-family",List.of(),List.of(),List.of(),anchors);DocxEditResult result=apply(bytes,plan,List.of());assertEquals(50,result.getNativeLayoutLedger().size());
        Document beforeDocument=parse(unzip(bytes).get(MAIN)),afterDocument=parse(unzip(result.getDocxBytes()).get(MAIN));assertEquals(10,beforeDocument.getElementsByTagNameNS(W,"vMerge").getLength());assertEquals(beforeDocument.getElementsByTagNameNS(W,"vMerge").getLength(),afterDocument.getElementsByTagNameNS(W,"vMerge").getLength());for(int i=0;i<beforeDocument.getElementsByTagNameNS(W,"vMerge").getLength();i++)assertEquals(shape((Element)beforeDocument.getElementsByTagNameNS(W,"vMerge").item(i)),shape((Element)afterDocument.getElementsByTagNameNS(W,"vMerge").item(i)),"All original merge restart/continuation values survive unchanged");
        for(NativeLayoutChange change:result.getNativeLayoutLedger()){assertEquals(ROW,change.getAction());assertEquals("APPLIED",change.getStatus());assertTrue(result.getIndex().paragraph(change.getGeneratedId()).hasNativeRowCohesion());Element original=at(beforeDocument,change.getSource().getId()),current=at(afterDocument,change.getSource().getId());List<Element> oldProps=children(original,"trPr"),newProps=children(current,"trPr");assertTrue(oldProps.size()<=1);assertEquals(1,newProps.size());List<Element> switches=children(newProps.get(0),"cantSplit");assertEquals(1,switches.size());assertEquals("1",switches.get(0).getAttributeNS(W,"val"));newProps.get(0).removeChild(switches.get(0));
            Element oldWithoutSwitch=oldProps.isEmpty()?beforeDocument.createElementNS(W,"w:trPr"):(Element)oldProps.get(0).cloneNode(true);for(Element originalSwitch:children(oldWithoutSwitch,"cantSplit"))oldWithoutSwitch.removeChild(originalSwitch);assertEquals(shape(oldWithoutSwitch),shape(newProps.get(0)),"Only the source-registered cantSplit switch may change row properties");if(oldProps.isEmpty())current.removeChild(newProps.get(0));else current.replaceChild(afterDocument.importNode(oldProps.get(0),true),newProps.get(0));}
        undoMarkers(afterDocument,result.getNativeLayoutLedger());String beforeShape=shape(beforeDocument.getDocumentElement()),afterShape=shape(afterDocument.getDocumentElement());assertFalse(beforeShape.isEmpty(),"Whole source XML observer must be nonempty");assertEquals(beforeShape,afterShape,"All text, cells, vertical merge restarts/continuations, grid, fields, font/spacing and real page controls must survive the exact registered-row inverse");unchanged(unzip(bytes),unzip(result.getDocxBytes()),Set.of(MAIN));assertEquals(index.getSourceSha256(),EDITOR.inspect(bytes).getSourceSha256());
    }

}
